@spec sample_page_spec  src=tests/specs/sample_page_spec.lua  loc=95  cases=5
@exercises commandManager (h.cmgr)
@surface   cmgr:installManifest, cmgr:scope
@harness   mk

# Intent
  Pin-tests for samplePage's Page interface (bind / unbind / focusState).
  Render methods pull in ImGui and are exercised manually in REAPER.
  
  samplePage requires ImGui at module scope; stub via package.preload
  before the first require so the module loads in the pure-Lua harness.

# Helpers
  @fn newSamplePage(cm, cmgr, chrome, gui)  @ 23-26

# Cases
  @case 'the manifest declares every command the sample page registers'  [harness]  @ 33-48
  @case 'setTrack(track) re-keys cm to that track via the page's own sv'  [harness]  @ 52-60
  @case 'setTrack(nil) does not re-key cm'  [harness]  @ 63-71
  @case 'focusState before any render returns both bits false'  [harness]  @ 74-81
  @case 'bind re-keys cm to the page track on every activation, not just the first'  [harness]  @ 84-93

# Uses (outbound edges)
  @use call cmgr:installManifest  @ 40
  @use call cmgr:scope  @ 42

# Fields (r read / w write incl. constructor keys)
  @field w ImGui_GetBuiltinPath  @ 16
  @field w Mod_None  @ 10
  @field w __index  @ 11
  @field r acceptCmds  @ 80
  @field w chrome  @ 25
  @field w cm  @ 25
  @field w cmgr  @ 25
  @field w currentTake  @ 21
  @field w facade  @ 25
  @field w get  @ 21
  @field w gui  @ 25
  @field r label  @ 45
  @field r manifest  @ 43
  @field w name  @ 33,52,63,74,84
  @field r preload  @ 13
